#include "config.h"
#include "baldr/graphreader.h"
#include <boost/property_tree/json_parser.hpp>
#include <set>
#include <iostream>
#include <cstring>
void need(bool x,const char*m){if(!x)throw std::runtime_error(m);}
int main(int argc,char**argv){try{using namespace valhalla::baldr;auto cfg=valhalla::config(argv[1]);GraphReader r(cfg.get_child("mjolnir"));auto orig=cfg;orig.put("mjolnir.tile_dir",argv[3]);GraphReader before(orig.get_child("mjolnir"));boost::property_tree::ptree p;boost::property_tree::read_json(argv[2],p);std::set<uint64_t> ways,directed,walk,deny,mainlines;
for(auto&x:p.get_child("osm_motorway_mainlines"))mainlines.insert(x.second.get_value<uint64_t>());
for(auto&x:p.get_child("allow_motorway_ways"))ways.insert(x.second.get_value<uint64_t>());for(auto&x:p.get_child("allow_directed_edges"))directed.insert(x.second.get<uint64_t>("graph_id"));for(auto&x:p.get_child("walk_bicycle_ways"))walk.insert(x.second.get_value<uint64_t>());for(auto&x:p.get_child("deny_ways"))deny.insert(x.second.get_value<uint64_t>());
uint64_t checked=0,motorways=0,walking=0,removed=0;std::set<uint64_t> denied_ways;
for(auto id:r.GetTileSet()){auto t=r.GetGraphTile(id),old=before.GetGraphTile(id);need(bool(old),"missing original tile");need(t->header()->nodecount()==old->header()->nodecount()&&t->header()->directededgecount()==old->header()->directededgecount(),"topology counts changed");if(t->header()->nodecount()==0){need(t->header()->directededgecount()==0,"Empty-node tile contains edges");continue;}need(std::memcmp(t->node(0),old->node(0),sizeof(NodeInfo)*t->header()->nodecount())==0,"node data changed");for(uint32_t i=0;i<t->header()->directededgecount();++i){auto e=t->directededge(i),o=old->directededge(i);auto w=t->edgeinfo(e).wayid();auto gid=GraphId(id.tileid(),id.level(),i);auto copy=*e;copy.set_forwardaccess(o->forwardaccess());copy.set_reverseaccess(o->reverseaccess());copy.set_dismount(o->dismount());need(std::memcmp(&copy,o,sizeof copy)==0,"non-access edge attributes changed");if(walk.count(w)){need(e->dismount(),"walk edge missing dismount");need(bool(o->forwardaccess()&kPedestrianAccess)&&bool(o->reverseaccess()&kPedestrianAccess),"walk lacks pedestrian access");++walking;}else{need((e->forwardaccess()|o->forwardaccess())==o->forwardaccess(),"unauthorized forward grant");need((e->reverseaccess()|o->reverseaccess())==o->reverseaccess(),"unauthorized reverse grant");need(e->dismount()==o->dismount(),"unauthorized dismount change");}if(!e->is_shortcut()&&(e->classification()==RoadClass::kMotorway||mainlines.count(w)||deny.count(w))){++motorways;if(deny.count(w)||(!ways.count(w)&&!directed.count(gid.value)))need(!(e->forwardaccess()&kBicycleAccess),"prohibited forward motorway");if(deny.count(w)||(!ways.count(w)&&!directed.count(r.GetOpposingEdgeId(gid).value)))need(!(e->reverseaccess()&kBicycleAccess),"prohibited reverse motorway");}if((o->forwardaccess()&kBicycleAccess)&&!(e->forwardaccess()&kBicycleAccess)){++removed;denied_ways.insert(w);}++checked;}}
const uint64_t expected_walking = argc > 4 ? std::stoull(argv[4]) : 10;
need(walking==expected_walking,"unexpected walking directed edge count");std::cout<<"{\"passed\":true,\"edges_checked\":"<<checked<<",\"motorway_or_denied_edges\":"<<motorways<<",\"walking_edges\":"<<walking<<",\"removed_forward_access\":"<<removed<<",\"denied_ways\":[";bool comma=false;for(auto w:denied_ways){if(comma)std::cout<<',';comma=true;std::cout<<w;}std::cout<<"]}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
